<?php require_once 'funciones.php'; exigir_login(); if(($_SESSION['rol']??'')!=='cliente'){header('Location: admin/index.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['actualizar'])){foreach(($_POST['cant']??[]) as $id=>$cant){$cant=(int)$cant;if($cant<=0)unset($_SESSION['carrito'][$id]);else $_SESSION['carrito'][(int)$id]=min(20,$cant);}}if(isset($_POST['vaciar']))$_SESSION['carrito']=[];header('Location: carrito.php');exit;}
$items=[];$subtotal=0;foreach(($_SESSION['carrito']??[]) as $id=>$cant){$id=(int)$id;$q=$conn->prepare('SELECT id,nombre,precio,imagen FROM productos WHERE id=? AND activo=1');$q->bind_param('i',$id);$q->execute();$p=$q->get_result()->fetch_assoc();if($p){$p['cantidad']=(int)$cant;$p['importe']=$p['cantidad']*(float)$p['precio'];$subtotal+=$p['importe'];$items[]=$p;}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi carrito</title><link rel="stylesheet" href="estilos.css"></head><body><div class="barra">COMO EN CASA <span><a href="tienda.php">← Seguir comprando</a></span></div><main class="contenedor"><h1 class="titulo">Mi carrito</h1><?php mostrar_aviso();?><?php if(!$items):?><div class="panel">Tu carrito está vacío. <a href="tienda.php" style="color:var(--vino)">Ver menú</a></div><?php else:?><form method="post" class="panel"><div class="tabla-wrap"><table><tr><th>Producto</th><th>Precio</th><th>Cantidad</th><th>Importe</th></tr><?php foreach($items as $p):?><tr><td><?=e($p['nombre'])?></td><td>S/ <?=number_format($p['precio'],2)?></td><td><input type="number" min="0" max="20" name="cant[<?=$p['id']?>]" value="<?=$p['cantidad']?>" style="width:75px;padding:7px"></td><td>S/ <?=number_format($p['importe'],2)?></td></tr><?php endforeach;?></table></div><div class="fila" style="margin-top:18px"><button class="btn btn-claro" name="actualizar">Actualizar carrito</button><button class="btn btn-claro" name="vaciar">Vaciar</button><strong class="precio">Subtotal: S/ <?=number_format($subtotal,2)?></strong><a class="btn btn-vino" href="checkout.php">Continuar pedido</a></div></form><?php endif;?></main></body></html>
